begin;
set local search_path=public,extensions;
select no_plan();
select has_function('public','get_meetup_upcoming_sessions',array['uuid'],'upcoming reader exists separately from history');
select set_config('test.history_hash',md5(pg_get_functiondef('public.get_meetup_sessions(uuid)'::regprocedure)),true);
insert into auth.users(id,email) select ('e2358000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'upcoming-'||n||'@example.test' from generate_series(1,3)n;
insert into public.profiles(id,nickname,city_id) select id,'Upcoming fixture '||right(id::text,1),'vancouver' from auth.users where id::text like 'e2358000-%';
insert into public.posts(id,author_id,city_id,tag_id,title,body,room_preview) values
 ('e2359000-0000-4000-8000-000000000001','e2358000-0000-4000-8000-000000000001','vancouver',1,'Upcoming fixture','Synthetic meetup','{"eventKind":"group","cadence":"weekly","capacity":8}');
insert into public.meetup_requests(post_id,host_id,requester_id,status) values
 ('e2359000-0000-4000-8000-000000000001','e2358000-0000-4000-8000-000000000001','e2358000-0000-4000-8000-000000000002','approved');
insert into private.meetup_sessions(id,post_id,host_id,starts_at,ends_at)
 select ('e235a000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'e2359000-0000-4000-8000-000000000001','e2358000-0000-4000-8000-000000000001',now()+n*interval '1 day',now()+n*interval '1 day'+interval '2 hours' from generate_series(1,13)n;
insert into private.meetup_sessions(id,post_id,host_id,starts_at,ends_at) values
 ('e235a000-0000-4000-8000-000000000014','e2359000-0000-4000-8000-000000000001','e2358000-0000-4000-8000-000000000001',now()-interval '1 hour',now()+interval '1 hour'),
 ('e235a000-0000-4000-8000-000000000015','e2359000-0000-4000-8000-000000000001','e2358000-0000-4000-8000-000000000001',now()-interval '3 hours',now()-interval '2 hours');
select set_config('request.jwt.claims','{"sub":"e2358000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select is(jsonb_array_length(public.get_meetup_upcoming_sessions('e2359000-0000-4000-8000-000000000001')->'sessions'),12,'thirteen future plus ongoing sessions are bounded at twelve');
select is(public.get_meetup_upcoming_sessions('e2359000-0000-4000-8000-000000000001')->'sessions'->0->>'id','e235a000-0000-4000-8000-000000000014','ongoing session is first');
select is(public.get_meetup_upcoming_sessions('e2359000-0000-4000-8000-000000000001')->'sessions'->1->>'id','e235a000-0000-4000-8000-000000000001','the actual closest future session is retained');
select is(public.get_meetup_upcoming_sessions('e2359000-0000-4000-8000-000000000001')->'sessions'->11->>'id','e235a000-0000-4000-8000-000000000011','only nearest twelve active/future records are returned');
select ok(public.get_meetup_upcoming_sessions('e2359000-0000-4000-8000-000000000001')->'sessions'->0 ?& array['id','startsAt','endsAt','checkedIn','verified','claimStatus','reviewStatus','canReview','members'],'existing DTO and review projection fields are retained');
select is(public.get_meetup_sessions('e2359000-0000-4000-8000-000000000001')->'sessions'->0->>'id','e235a000-0000-4000-8000-000000000013','history reader keeps descending order');
reset role;
select set_config('request.jwt.claims','{"sub":"e2358000-0000-4000-8000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select is(public.get_meetup_upcoming_sessions('e2359000-0000-4000-8000-000000000001')->>'member','true','approved member uses existing attendance eligibility');
select is(jsonb_array_length(public.get_meetup_upcoming_sessions('e2359000-0000-4000-8000-000000000001')->'sessions'),12,'approved member sees the same nearest sessions');
reset role;
insert into public.blocks(blocker_id,blocked_id) values('e2358000-0000-4000-8000-000000000001','e2358000-0000-4000-8000-000000000002');
set local role authenticated;
select is(jsonb_array_length(public.get_meetup_upcoming_sessions('e2359000-0000-4000-8000-000000000001')->'sessions'),0,'blocked former member cannot read session dates');
select is(public.get_meetup_upcoming_sessions('e2359000-0000-4000-8000-000000000001')->>'member','false','blocked context exposes no member capability');
select is(public.get_meetup_upcoming_sessions('e2359000-0000-4000-8000-000000000001')->>'isHost','false','blocked context exposes no host capability');
reset role;
delete from public.blocks where blocker_id='e2358000-0000-4000-8000-000000000001' and blocked_id='e2358000-0000-4000-8000-000000000002';
insert into public.reports(reporter_id,reported_user_id,target_type,target_id,reason_code,details) values('e2358000-0000-4000-8000-000000000002','e2358000-0000-4000-8000-000000000001','post','e2359000-0000-4000-8000-000000000001','other','Synthetic hide');
set local role authenticated;
select is(jsonb_array_length(public.get_meetup_upcoming_sessions('e2359000-0000-4000-8000-000000000001')->'sessions'),0,'report-hidden meetup dates stay private');
select is(public.get_meetup_upcoming_sessions('e2359000-0000-4000-8000-000000000001')->>'member','false','reported context cannot look like an empty active membership');
reset role;
delete from public.reports where reporter_id='e2358000-0000-4000-8000-000000000002' and target_id='e2359000-0000-4000-8000-000000000001';
update public.profiles set account_status='suspended' where id='e2358000-0000-4000-8000-000000000001';
set local role authenticated;
select is(public.get_meetup_upcoming_sessions('e2359000-0000-4000-8000-000000000001')->>'member','false','inactive host context has no current capability');
reset role;
update public.profiles set account_status='active' where id='e2358000-0000-4000-8000-000000000001';
update public.profiles set account_status='suspended' where id='e2358000-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok($$select public.get_meetup_upcoming_sessions('e2359000-0000-4000-8000-000000000001')$$,'P0001',null,'inactive viewer retains active-account denial');
reset role;
update public.profiles set account_status='active' where id='e2358000-0000-4000-8000-000000000002';
select set_config('request.jwt.claims','{"sub":"e2358000-0000-4000-8000-000000000003","role":"authenticated"}',true);
set local role authenticated;
select is(public.get_meetup_upcoming_sessions('e2359000-0000-4000-8000-000000000001')->>'member','false','nonmember retains existing empty DTO');
select is(jsonb_array_length(public.get_meetup_upcoming_sessions('e2359000-0000-4000-8000-000000000001')->'sessions'),0,'nonmember sees no dates');
reset role;
select set_config('request.jwt.claims','{"sub":"e2358000-0000-4000-8000-000000000002","role":"authenticated"}',true);
savepoint before_unpublish;
update public.posts set status='removed' where id='e2359000-0000-4000-8000-000000000001';
set local role authenticated;
select is(public.get_meetup_upcoming_sessions('e2359000-0000-4000-8000-000000000001')->>'member','false','unpublished meetup context exposes no member capability');
select is(jsonb_array_length(public.get_meetup_upcoming_sessions('e2359000-0000-4000-8000-000000000001')->'sessions'),0,'unpublished meetup dates stay private');
reset role;
rollback to savepoint before_unpublish;
update public.posts set room_preview=room_preview||'{"closed":true}' where id='e2359000-0000-4000-8000-000000000001';
set local role authenticated;
select is(public.get_meetup_upcoming_sessions('e2359000-0000-4000-8000-000000000001')->>'member','false','closed meetup context has no current capability');
reset role;
select ok(not has_function_privilege('anon','public.get_meetup_upcoming_sessions(uuid)','execute'),'guest execution is not granted');
select ok(has_function_privilege('authenticated','public.get_meetup_upcoming_sessions(uuid)','execute'),'authenticated grant is preserved');
select set_config('request.jwt.claims','{"role":"anon"}',true);
set local role authenticated;
select throws_ok($$select public.get_meetup_upcoming_sessions('e2359000-0000-4000-8000-000000000001')$$,'P0001','AUTH_REQUIRED','missing user cannot use an authenticated role to bypass auth');
reset role;
set local role anon;
select throws_ok($$select public.get_meetup_upcoming_sessions('e2359000-0000-4000-8000-000000000001')$$,'42501',null,'actual guest execution is denied');
reset role;
select is(md5(pg_get_functiondef('public.get_meetup_sessions(uuid)'::regprocedure)),current_setting('test.history_hash'),'history definition stays unchanged through all reads');
select * from finish();
rollback;
